// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 value, bytes calldata data, uint256 ethAmount) public {
        vm.assume(caller != address(this));
        vm.deal(address(this), 1000 ether);
        vm.prank(address(this));
        (bool depositOk,) = address(c).call{value: 1000 ether}("");
        require(depositOk, "deposit failed");
        vm.deal(caller, value);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(0), value, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
